export interface ExtractionRule {
  id: string;
  dimension: FingerprintDimension;
  value: string;
  phrase: RegExp;
  confidence: 'HIGH' | 'MEDIUM';
}
const direct = (
  dimension: FingerprintDimension,
  value: string,
  phrase: string,
  confidence: 'HIGH' | 'MEDIUM' = 'HIGH',
): ExtractionRule => ({
  id: `${dimension}:${value}`,
  dimension,
  value,
  phrase: new RegExp(`(?<![\\p{L}\\p{N}])(?:${phrase})(?![\\p{L}\\p{N}])`, 'giu'),
  confidence,
});
